// Counter-pick engine. Every input is a verified skill tag from hero-tags.json
// (generated by scripts/build-hero-tags.mjs). Scores are rule-derived heuristics,
// not win rates — the UI must label them as such.
const clamp=(n,lo,hi)=>Math.max(lo,Math.min(hi,n))

// Traits each hero carries, when facing an enemy hero.
export const EDGES=[
  {id:'lock',weight:26,when:(a,b)=>b.dash&&a.cc>=1,label:'สกิลควบคุมตัดจังหวะเคลื่อนที่',
   why:'มีสกิลควบคุม ตัดจังหวะสกิลเคลื่อนที่และจังหวะเข้าของเป้าหมาย'},
  {id:'poke',weight:20,when:(a,b)=>a.poke&&!b.dash&&b.cc<2,label:'โปะใส่ตัวไม่มีสกิลเข้าถึง',
   why:'ยืนระยะไกลได้ เพราะเป้าหมายไม่มีสกิลเข้าถึงตัวและคุมไม่พอ'},
  {id:'dive',weight:30,when:(a,b)=>a.dive&&b.poke&&b.cc<2,label:'พุ่งถึงแนวหลัง',
   why:'มีจังหวะพุ่งเข้าถึงแนวหลังที่ยืนระยะไกล'},
  {id:'true',weight:24,when:(a,b)=>a.trueDmg&&(b.tanky||b.mitigate),label:'ดาเมจจริงเจาะตัวหนา',
   why:'ดาเมจจริงลดผลของความหนาและตัวลดดาเมจ'},
  {id:'unseen',weight:24,when:(a,b)=>a.invis&&!b.vision,label:'เข้าจังหวะไร้ตำแหน่ง',
   why:'เข้าจังหวะได้ เพราะเป้าหมายไม่มีเครื่องมือเปิดตำแหน่ง'},
  {id:'burst',weight:22,when:(a,b)=>a.burst&&!b.tanky&&!b.mitigate,label:'เบิร์สต์ใส่ตัวบาง',
   why:'จังหวะเบิร์สต์ปิดงานเป้าหมายที่ไม่มีเกราะหรือตัวลดดาเมจ'},
  {id:'outlast',weight:18,when:(a,b)=>a.sustain&&b.burst&&!b.trueDmg,label:'ฟื้นฟูเกินเบิร์สต์',
   why:'ฟื้นฟูต่อเนื่องทำให้จังหวะเบิร์สต์ของเป้าหมายปิดไม่ได้'}
]

// Mutual: both directions counted, then subtracted.
export function edgesFor(a,b){
  if(!a||!b||a.id===b.id)return []
  return EDGES.filter(e=>e.when(a,b))
}

export function counterScore(a,b){
  if(!a||!b||a.id===b.id)return {score:0,why:[],against:[],net:0}
  const mine=edgesFor(a,b),theirs=edgesFor(b,a)
  const fa=mine.reduce((n,e)=>n+e.weight,0)
  const fb=theirs.reduce((n,e)=>n+e.weight,0)
  return {
    score:clamp(fa-fb,-99,99),
    net:fa-fb,
    why:mine.map(e=>e.why),
    against:theirs.map(e=>e.why)
  }
}

// Calibrated on the 130-hero roster: |score| >= 60 is the rarest, clearest tier.
export const BANDS={win:60,good:24,lose:-24,bad:-60}
export const verdict=score=>score>=BANDS.win?{id:'win',label:'ชนะทางชัด'}
 :score>=BANDS.good?{id:'good',label:'ได้เปรียบ'}
 :score>BANDS.lose?{id:'even',label:'พอ ๆ กัน'}
 :score>BANDS.bad?{id:'lose',label:'เสียเปรียบ'}
 :{id:'bad',label:'แพ้ทางชัด'}

export function rank(heroId,heroes,tags,limit=8){
  const self=heroes.find(h=>h.id===heroId)
  if(!self)return {beats:[],loses:[]}
  const a={...self,...tags[heroId]}
  const rows=heroes.filter(h=>h.id!==heroId).map(h=>{
    const {score,why,against}=counterScore(a,{...h,...tags[h.id]})
    return {hero:h,score,why,against}
  })
  return {
    beats:rows.filter(r=>r.score>0).sort((x,y)=>y.score-x.score).slice(0,limit),
    loses:rows.filter(r=>r.score<0).sort((x,y)=>x.score-y.score).slice(0,limit)
  }
}

// Best answers to the enemy lineup, from the available pool only.
export function answersTo(enemyIds,pool,heroes,tags,limit=6){
  const enemy=enemyIds.map(id=>heroes.find(h=>h.id===id)).filter(Boolean).map(h=>({...h,...tags[h.id]}))
  if(!enemy.length)return []
  return pool.filter(h=>!enemyIds.includes(h.id)).map(h=>{
    const me={...h,...tags[h.id]}
    const detail=enemy.map(e=>({hero:e,...counterScore(me,e)}))
    const score=detail.reduce((n,d)=>n+d.score,0)
    return {hero:h,score,detail:detail.filter(d=>d.score>0).sort((x,y)=>y.score-x.score)}
  }).filter(r=>r.score>0).sort((x,y)=>y.score-x.score).slice(0,limit)
}

// A player's comfort pool vs the heroes they will meet in each lane they play.
// entries: [{id,lane}] (lane = where the player uses that hero). "Faced" = heroes
// listed in that lane, i.e. the lane opponent. strong = we hold a clear answer;
// weak = it beats one of ours and nothing in the pool answers it. Ties go to
// the higher ranked pick rate, since those are the ones met first.
export function poolReport(entries,heroes,tags,limit=5){
  const byId=new Map(heroes.map(h=>[h.id,h])),T=h=>({...h,...tags[h.id]})
  const pick=h=>h.pick??0
  return [...new Set(entries.map(e=>e.lane))].map(lane=>{
    const mine=entries.filter(e=>e.lane===lane).map(e=>byId.get(e.id)).filter(Boolean)
    const own=new Set(mine.map(h=>h.id))
    const faced=heroes.filter(h=>h.lane===lane&&!own.has(h.id))
    const rows=faced.map(e=>{
      const vs=mine.map(m=>({hero:m,...counterScore(T(m),T(e))})).sort((a,b)=>b.score-a.score)
      return {hero:e,best:vs[0],worst:vs[vs.length-1],beatsUs:vs.filter(v=>v.score<=BANDS.lose).map(v=>v.hero)}
    })
    const strong=rows.filter(r=>r.best.score>=BANDS.good)
      .sort((a,b)=>b.best.score-a.best.score||pick(b.hero)-pick(a.hero))
    const weak=rows.filter(r=>r.best.score<BANDS.good&&r.beatsUs.length)
      .sort((a,b)=>b.beatsUs.length-a.beatsUs.length||a.best.score-b.best.score||pick(b.hero)-pick(a.hero))
    return {lane,mine,faced:faced.length,covered:strong.length,strong:strong.slice(0,limit),weak:weak.slice(0,limit),weakTotal:weak.length}
  })
}
